import math
from typing import Callable, List

Func = Callable[[float], float]

def relu(x: float) -> float:
    return x if x > 0.0 else 0.0

def relu_interp_net(f: Func, n: int, x: float) -> float:
    total = f(0.0)
    for k in range(n):
        s = n * (f((k + 1) / n) - f(k / n))
        total += s * (relu(x - k / n) - relu(x - (k + 1) / n))
    return total

def sup_error(f: Func, n: int, samples: int = 4001) -> float:
    return max(abs(relu_interp_net(f, n, i / (samples - 1)) - f(i / (samples - 1)))
               for i in range(samples))

def slope(ns: List[int], errs: List[float]) -> float:
    pts = [(math.log2(n), math.log2(e)) for n, e in zip(ns, errs) if e > 0]
    m = len(pts); sx = sum(p[0] for p in pts); sy = sum(p[1] for p in pts)
    sxx = sum(p[0] ** 2 for p in pts); sxy = sum(p[0] * p[1] for p in pts)
    return (m * sxy - sx * sy) / (m * sxx - sx * sx)

ns = [8, 16, 32, 64, 128, 256]
rough = [sup_error(lambda x: abs(x - 1.0 / 3.0), n) for n in ns]
smooth = [sup_error(lambda x: x * x, n) for n in ns]
print('Lipschitz |x-1/3| exponent:', round(slope(ns, rough), 3))
print('Smooth    x^2      exponent:', round(slope(ns, smooth), 3))

